import os,json,subprocess
from pathlib import Path
root=Path("/srv/projects/iptvpn-bot")
legacy=("/root/iptvpn_bot","/etc/iptvpn-bot","/root/project-secrets/iptvpn_bot","/tmp/iptvpn_bot.lock")
out={"root":{},"aliases":{},"references":{},"live":{},"services":{}}
for rel in ("start.sh","main.py","config","private","data","tools/pm2","archive",".pm2"):
 p=root/rel;out["root"][rel]={"exists":p.exists(),"real":not p.is_symlink(),"is_dir":p.is_dir(),"is_file":p.is_file()}
s=(root/"start.sh").read_text(errors="replace") if (root/"start.sh").is_file() else ""
out["root"]["start_sh_safe_lines"]=[line for line in s.splitlines() if line.startswith(("LOCK=","LOG=","PY=","cd "))][:8]
for a in legacy:
 p=Path(a);out["aliases"][a]={"symlink":p.is_symlink(),"exists":p.exists(),"target":os.readlink(a) if p.is_symlink() else None}
for n in ("ssh","nginx","pm2-root","pm2-iptvpn-bot","lowcost-europa","fadego-staging"):
 out["services"][n]=subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip()
for home,name in (("/root/.pm2","global"),(str(root/".pm2"),"private")):
 binary=["/usr/bin/pm2"] if name=="global" else ["/usr/bin/node",str(root/"tools/pm2/bin/pm2")]
 try:
  r=subprocess.run(binary+["jlist"],env=dict(os.environ,PM2_HOME=home),capture_output=True,text=True,timeout=12)
  if r.returncode==0:
   apps=json.loads(r.stdout)
   out["live"][name]=[{"name":a.get("name"),"pid":a.get("pid"),"status":(a.get("pm2_env")or{}).get("status"),"cwd":(a.get("pm2_env")or{}).get("pm_cwd"),"exec":(a.get("pm2_env")or{}).get("pm_exec_path")} for a in apps]
 except Exception as e:out["live"][name]={"error":type(e).__name__}
base=("/etc/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin",str(root))
n=0
for b in base:
 p=Path(b)
 if not p.is_dir():continue
 for cur,dirs,files in os.walk(p,followlinks=False):
  ds=Path(cur).relative_to(p).parts
  if len(ds)>3:dirs[:]=[];continue
  dirs[:]=[x for x in dirs if x not in ("node_modules",".venv",".git","archive","private","config","tools","logs","data","__pycache__")]
  for name in files:
   f=Path(cur)/name
   try:
    if f.is_symlink() or not f.is_file() or f.stat().st_size>85000:continue
    n+=1
    data=f.read_bytes()
    for old in legacy[:3]:
     if old.encode() in data:out["references"].setdefault(old,[]).append(str(f))
   except OSError:pass
out["files_scanned"]=n
print(json.dumps(out,sort_keys=True))
